// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @dev Interfaz mínima para llamar al Vigilante de Auto-Amortización.
 * BlueToken usa esta interfaz para notificar a WintonProtocol cada vez
 * que alguien recibe tokens BLUE, activando la Regla Materia-Antimateria.
 */
interface IAutoAmortizer {
    function triggerAutoAmortize(address user) external;
}

/**
 * @title BlueToken (Winton BLUE)
 * @author WintonCoin Protocol Team
 * @notice El activo líquido del ecosistema WintonCoin. Cumple ERC-20.
 * @dev Su emisión y quema están estrictamente controladas por el contrato
 * WintonProtocol para asegurar la Regla de Balance Cero (Materia-Antimateria).
 *
 * SEGURIDAD:
 * - La dirección del Protocolo se asigna UNA SOLA VEZ (inmutable post-configuración).
 * - Solo WintonProtocol puede mintear o quemar tokens.
 * - El Owner no puede mintear tokens directamente, eliminando riesgo de rug-pull.
 * - VIGILANTE: Cada recepción de BLUE activa automáticamente la auto-amortización
 *   en WintonProtocol, haciendo imposible que coexistan BLUE y RED.
 */
contract BlueToken is ERC20, Ownable {

    /// @notice Dirección del contrato WintonProtocol autorizado para mintear/quemar.
    address public wintonProtocol;

    /// @notice Bandera de seguridad: true = el protocolo ya fue configurado y es irreversible.
    bool public protocolLocked;

    /// @notice Direcciones exentas del vigilante (Treasury, Protocol) para ahorrar gas.
    /// @dev Estas direcciones nunca tendrán deuda RED, así que revisarlas es innecesario.
    mapping(address => bool) public isExemptFromAmortization;

    /// @notice Evento auditable emitido al configurar el protocolo por única vez.
    event ProtocolSet(address indexed protocol);

    /// @notice Evento emitido al configurar una dirección exenta del vigilante.
    event ExemptionUpdated(address indexed addr, bool status);

    /// @notice Constructor del token. No mintea suministro inicial (Balance Cero).
    constructor() ERC20("Winton BLUE", "BLUE") Ownable(msg.sender) {}

    /**
     * @notice BLOQUEADO. No se permite renunciar a la propiedad del contrato.
     * @dev Sobreescribe Ownable.renounceOwnership() para prevenir que el protocolo
     * quede permanentemente sin administrador. En su lugar, usar transferOwnership()
     * para migrar el control a un Gnosis Safe (multisig) en producción.
     */
    function renounceOwnership() public pure override {
        revert("BLUE: Ownership renunciation is disabled");
    }

    /**
     * @notice Asigna la dirección del Motor Principal. IRREVERSIBLE.
     * @dev Solo puede llamarse una vez por el Owner. Después de esto, el Owner
     * pierde la capacidad de cambiar quién controla la emisión. Esto previene
     * que un atacante que comprometa la llave del Owner pueda redirigir el minteo.
     * @param _protocol Dirección del contrato WintonProtocol desplegado.
     */
    function setWintonProtocol(address _protocol) external onlyOwner {
        // SEGURIDAD: Solo se permite configurar una vez (Patrón de Bloqueo Irreversible).
        require(!protocolLocked, "BLUE: Protocol already locked");
        // SEGURIDAD: Prevenir configuración a dirección vacía (fondos irrecuperables).
        require(_protocol != address(0), "BLUE: Invalid zero address");

        // Asignar y bloquear permanentemente.
        wintonProtocol = _protocol;
        protocolLocked = true;

        // El propio protocolo está exento del vigilante (nunca tendrá deuda RED).
        isExemptFromAmortization[_protocol] = true;

        // Registro auditable del momento exacto de la configuración.
        emit ProtocolSet(_protocol);
    }

    /**
     * @notice Configura direcciones exentas del vigilante de auto-amortización.
     * @dev Solo el Owner puede ejecutar. Usar para la Treasury y otros contratos
     * del ecosistema que nunca tendrán deuda RED. Esto ahorra gas en cada transferencia.
     * @param _addr Dirección a exentar o des-exentar.
     * @param _status true = exenta (no se revisa), false = sujeta al vigilante.
     */
    function setExemptFromAmortization(address _addr, bool _status) external onlyOwner {
        require(_addr != address(0), "BLUE: Invalid zero address");
        isExemptFromAmortization[_addr] = _status;
        emit ExemptionUpdated(_addr, _status);
    }

    /// @dev Modificador que restringe funciones exclusivamente al WintonProtocol.
    modifier onlyProtocol() {
        require(msg.sender == wintonProtocol, "BLUE: Unauthorized. Only WintonProtocol");
        _;
    }

    /**
     * @notice Mintea nuevos tokens BLUE. Exclusivo del Motor Principal durante un pago.
     * @dev Solo WintonProtocol puede llamar esta función. El Owner NO puede.
     * @param to Dirección que recibirá los tokens minteados.
     * @param amount Cantidad de tokens a mintear (en wei, 18 decimales).
     */
    function mint(address to, uint256 amount) external onlyProtocol {
        _mint(to, amount);
    }

    /**
     * @notice Quema tokens BLUE. Exclusivo del Motor Principal durante la auto-amortización.
     * @dev Solo WintonProtocol puede llamar esta función. El Owner NO puede.
     * @param from Dirección cuyo saldo será reducido.
     * @param amount Cantidad de tokens a quemar (en wei, 18 decimales).
     */
    function burn(address from, uint256 amount) external onlyProtocol {
        _burn(from, amount);
    }

    // ========================================================================
    // EL VIGILANTE: Hook de Auto-Amortización en cada recepción de BLUE
    // ========================================================================

    /**
     * @notice Hook interno que se ejecuta en CADA movimiento de tokens (mint, burn, transfer).
     * @dev Sobreescribe la función _update de OpenZeppelin v5.
     * Después de que los tokens se mueven, verifica si el receptor tiene deuda RED.
     * Si la tiene, llama a WintonProtocol para destruir ambos (Materia-Antimateria).
     *
     * OPTIMIZACIONES DE GAS:
     * - No se activa para quemas (to == address(0)): no hay receptor que revisar.
     * - No se activa para direcciones exentas (Treasury, Protocol): nunca tienen RED.
     * - No se activa si el protocolo no fue configurado aún (fase de despliegue).
     * - Si la llamada al Protocolo falla por cualquier razón, la transferencia
     *   NO se revierte (try/catch). Esto previene que un bug en el Protocolo
     *   congele todos los movimientos de BLUE.
     *
     * @param from Dirección que envía los tokens (address(0) para mints).
     * @param to Dirección que recibe los tokens (address(0) para burns).
     * @param value Cantidad de tokens en movimiento.
     */
    function _update(address from, address to, uint256 value) internal override {
        // PASO 1: Ejecutar la transferencia/mint/burn normalmente (ERC-20 estándar).
        super._update(from, to, value);

        // PASO 2: Activar el Vigilante solo si se cumplen las condiciones.
        // - El receptor existe (no es una quema).
        // - El protocolo ya fue configurado.
        // - El receptor NO está en la lista de exentos.
        if (
            to != address(0) &&                      // No es una quema.
            wintonProtocol != address(0) &&           // El protocolo está configurado.
            !isExemptFromAmortization[to]             // El receptor no está exento.
        ) {
            // PASO 3: Llamar al Vigilante en WintonProtocol.
            // Usamos try/catch para que si el Protocolo falla por cualquier razón
            // (ej: no está inicializado), la transferencia de BLUE no se bloquee.
            try IAutoAmortizer(wintonProtocol).triggerAutoAmortize(to) {
                // Auto-amortización ejecutada exitosamente (o no había nada que quemar).
            } catch {
                // Si falla, simplemente continuamos. La transferencia ya se completó.
                // Esto previene que un bug en el Protocolo congele TODOS los tokens.
            }
        }
    }
}

contracts/RedToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title RedToken (Winton RED Debt)
 * @author WintonCoin Protocol Team
 * @notice Representación on-chain de la deuda en el ecosistema WintonCoin.
 * @dev A diferencia del BLUE, el RED NO es transferible entre usuarios.
 * Solo puede ser creado (cuando asumes deuda) o destruido (auto-amortización).
 * Los tokens RED se cancelan automáticamente al recibir BLUE (Materia-Antimateria).
 *
 * SEGURIDAD:
 * - transfer() y transferFrom() están permanentemente bloqueados (revert).
 * - approve() está bloqueado para prevenir ataques de allowance sobre deuda.
 * - La dirección del Protocolo se asigna UNA SOLA VEZ (inmutable post-configuración).
 * - Solo WintonProtocol puede mintear o quemar deuda.
 */
contract RedToken is ERC20, Ownable {

    /// @notice Dirección del contrato WintonProtocol autorizado para mintear/quemar deuda.
    address public wintonProtocol;

    /// @notice Bandera de seguridad: true = el protocolo ya fue configurado y es irreversible.
    bool public protocolLocked;

    /// @notice Evento auditable emitido al configurar el protocolo por única vez.
    event ProtocolSet(address indexed protocol);

    /// @notice Constructor del token de deuda. No mintea suministro inicial (Balance Cero).
    constructor() ERC20("Winton RED Debt", "RED") Ownable(msg.sender) {}

    /**
     * @notice BLOQUEADO. No se permite renunciar a la propiedad del contrato.
     * @dev Sobreescribe Ownable.renounceOwnership() para prevenir que el protocolo
     * quede permanentemente sin administrador. En su lugar, usar transferOwnership()
     * para migrar el control a un Gnosis Safe (multisig) en producción.
     */
    function renounceOwnership() public pure override {
        revert("RED: Ownership renunciation is disabled");
    }

    /**
     * @notice Asigna la dirección del Motor Principal. IRREVERSIBLE.
     * @dev Solo puede llamarse una vez por el Owner. Patrón de Bloqueo Irreversible.
     * @param _protocol Dirección del contrato WintonProtocol desplegado.
     */
    function setWintonProtocol(address _protocol) external onlyOwner {
        // SEGURIDAD: Solo se permite configurar una vez.
        require(!protocolLocked, "RED: Protocol already locked");
        // SEGURIDAD: Prevenir configuración a dirección vacía.
        require(_protocol != address(0), "RED: Invalid zero address");

        // Asignar y bloquear permanentemente.
        wintonProtocol = _protocol;
        protocolLocked = true;

        // Registro auditable.
        emit ProtocolSet(_protocol);
    }

    /// @dev Modificador que restringe funciones exclusivamente al WintonProtocol.
    modifier onlyProtocol() {
        require(msg.sender == wintonProtocol, "RED: Unauthorized. Only WintonProtocol");
        _;
    }

    /**
     * @notice Asigna deuda al usuario (Mintea RED).
     * @dev Solo WintonProtocol puede llamar esta función durante processPayment().
     * @param to Dirección del deudor que recibirá la deuda.
     * @param amount Cantidad de deuda a asignar (en wei, 18 decimales).
     */
    function mintDebt(address to, uint256 amount) external onlyProtocol {
        _mint(to, amount);
    }

    /**
     * @notice Cancela deuda del usuario (Quema RED) durante auto-amortización.
     * @dev Solo WintonProtocol puede llamar esta función.
     * @param from Dirección del deudor cuya deuda será reducida.
     * @param amount Cantidad de deuda a cancelar (en wei, 18 decimales).
     */
    function burnDebt(address from, uint256 amount) external onlyProtocol {
        _burn(from, amount);
    }

    /**
     * @notice BLOQUEADO. La deuda no se puede transferir a otro usuario.
     * @dev Previene que un deudor escape de su responsabilidad enviando 
     * su deuda a una billetera desechable o a un tercero inocente.
     */
    function transfer(address, uint256) public pure override returns (bool) {
        revert("RED: Debt tokens are non-transferable");
    }

    /// @notice BLOQUEADO. Previene transferencias delegadas de deuda.
    function transferFrom(address, address, uint256) public pure override returns (bool) {
        revert("RED: Debt tokens are non-transferable");
    }

    /**
     * @notice BLOQUEADO. No se permite aprobar allowances sobre deuda.
     * @dev Previene un vector de ataque donde un contrato malicioso podría
     * manipular la deuda de un usuario mediante approve + transferFrom.
     */
    function approve(address, uint256) public pure override returns (bool) {
        revert("RED: Debt tokens cannot be approved");
    }
}

contracts/WintonProtocol.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

// ============================================================================
// INTERFACES: Contratos externos con los que interactúa el Motor Central.
// ============================================================================

/// @dev Interfaz mínima del token BLUE para mintear, quemar y consultar saldo.
interface IBlueToken {
    function mint(address to, uint256 amount) external;
    function burn(address from, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

/// @dev Interfaz mínima del token RED para mintear deuda, quemar deuda y consultar saldo.
interface IRedToken {
    function mintDebt(address to, uint256 amount) external;
    function burnDebt(address from, uint256 amount) external;
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title WintonProtocol (El Motor Central del Ecosistema)
 * @author WintonCoin Protocol Team
 * @notice Implementa las Leyes Económicas de Creación y Destrucción Simultánea
 * (Materia-Antimateria), el Muro KYC On-Chain y el sistema de pausa de emergencia.
 *
 * @dev ARQUITECTURA EIP-7702 (Pectra / Isthmus):
 * Este contrato está diseñado para funcionar con EIP-7702 en Optimism.
 * A diferencia de ERC-2771, NO necesita un Trusted Forwarder ni overrides
 * de _msgSender(). Con EIP-7702, el Relayer (backend) envía transacciones
 * patrocinadas donde msg.sender ya es la identidad real del usuario.
 *
 * El Relayer es una dirección autorizada que actúa como intermediario:
 * - Valida los límites de crédito (WTS Score) en el backend.
 * - Verifica la firma del usuario mediante EIP-7702.
 * - Envía la transacción a la blockchain pagando el gas.
 * - Pasa la dirección del pagador como parámetro verificado.
 *
 * SEGURIDAD IMPLEMENTADA:
 * - ReentrancyGuard en processPayment (previene ataques de bucle infinito).
 * - Pausable (permite detener el protocolo si se detecta una vulnerabilidad).
 * - onlyRelayerOrOwner (impide que usuarios salten las validaciones del backend).
 * - Validación de dirección cero en toda configuración.
 * - Validación payer != payee (previene auto-pagos inflacionarios).
 * - Validación de treasury configurado antes de procesar pagos.
 * - Cap de comisión máxima al 50% (previene errores de configuración destructivos).
 * - Circuit Breaker: límite máximo por transacción individual.
 * - Eventos en todas las funciones de estado para trazabilidad completa.
 */
contract WintonProtocol is Ownable, ReentrancyGuard, Pausable {

    // ========================================================================
    // ESTADO: Variables que definen el estado del protocolo.
    // ========================================================================

    /// @notice Referencia al contrato del token BLUE (activo líquido).
    IBlueToken public blueToken;

    /// @notice Referencia al contrato del token RED (registro de deuda).
    IRedToken public redToken;

    /// @notice Dirección del contrato WintonTreasury (bóveda de comisiones).
    address public treasury;

    /// @notice Dirección del Relayer autorizado (backend que paga gas vía EIP-7702).
    address public relayer;

    /// @notice Tasa de comisión actual en porcentaje (ej: 5 = 5%).
    uint256 public commissionRate = 5;

    /// @notice Límite máximo de tokens por transacción individual (previene errores catastróficos).
    /// @dev Valor inicial: 1,000,000 BLUE (en wei = 1e24). Ajustable por el Owner.
    uint256 public maxTransactionAmount = 1_000_000 * 1e18;

    /// @notice Muro KYC On-Chain: solo billeteras verificadas pueden operar.
    mapping(address => bool) public isKYCVerified;

    // ========================================================================
    // EVENTOS: Registro inmutable en la blockchain para auditoría total.
    // ========================================================================

    /// @notice Emitido cuando se procesa un pago exitosamente.
    event PaymentProcessed(
        address indexed payer,    // Quien paga (recibe deuda RED).
        address indexed payee,    // Quien recibe (recibe BLUE líquido).
        uint256 amountBlue,       // Monto neto pagado al beneficiario.
        uint256 fee               // Monto de comisión enviado a la Tesorería.
    );

    /// @notice Emitido cuando se ejecuta la auto-amortización (Materia-Antimateria).
    event AutoAmortization(
        address indexed user,     // El usuario cuyo BLUE y RED fueron quemados.
        uint256 amountBurned      // Cantidad simultánea destruida de cada token.
    );

    /// @notice Emitido cuando el Owner actualiza las direcciones de los contratos.
    event ContractsUpdated(address blue, address red, address treasuryAddr);

    /// @notice Emitido cuando el Owner actualiza el estado KYC de una billetera.
    event KYCStatusUpdated(address indexed wallet, bool status);

    /// @notice Emitido cuando el Owner modifica la tasa de comisión.
    event CommissionRateUpdated(uint256 oldRate, uint256 newRate);

    /// @notice Emitido cuando el Owner modifica el límite máximo por transacción.
    event MaxTransactionAmountUpdated(uint256 oldAmount, uint256 newAmount);

    /// @notice Emitido cuando el Owner cambia la dirección del Relayer.
    event RelayerUpdated(address indexed oldRelayer, address indexed newRelayer);

    // ========================================================================
    // CONSTRUCTOR
    // ========================================================================

    /**
     * @notice Inicializa el protocolo. El deployer es Owner y Relayer inicial.
     * @dev Con EIP-7702, no se necesita Trusted Forwarder. El Relayer es la
     * billetera del backend que patrocina las transacciones de los usuarios.
     * @param _relayer Dirección del Relayer (backend) que pagará el gas.
     */
    constructor(address _relayer) Ownable(msg.sender) {
        // SEGURIDAD: El Relayer debe ser una dirección válida.
        require(_relayer != address(0), "WintonProtocol: Invalid relayer address");
        relayer = _relayer;
        emit RelayerUpdated(address(0), _relayer);
    }

    /**
     * @notice BLOQUEADO. No se permite renunciar a la propiedad del contrato.
     * @dev Sobreescribe Ownable.renounceOwnership() para prevenir que el protocolo
     * quede permanentemente sin administrador. En su lugar, usar transferOwnership()
     * para migrar el control a un Gnosis Safe (multisig) en producción.
     */
    function renounceOwnership() public pure override {
        revert("WintonProtocol: Ownership renunciation is disabled");
    }

    // ========================================================================
    // MODIFICADOR DE SEGURIDAD: Solo Relayer o Owner
    // ========================================================================

    /**
     * @dev Restringe la ejecución a llamadas del Relayer (backend) o del Owner.
     * Esto impide que un usuario KYC verificado llame processPayment directamente
     * desde MetaMask, saltando las validaciones de crédito del backend (WTS Score).
     */
    modifier onlyRelayerOrOwner() {
        require(
            msg.sender == relayer || msg.sender == owner(),
            "WintonProtocol: Only Relayer or Owner"
        );
        _;
    }

    // ========================================================================
    // FUNCIONES DE CONFIGURACIÓN (Solo Owner)
    // ========================================================================

    /**
     * @notice Configura las direcciones de los contratos del ecosistema.
     * @dev Solo el Owner puede ejecutar. Todas las direcciones deben ser válidas.
     * @param _blue Dirección del contrato BlueToken desplegado.
     * @param _red Dirección del contrato RedToken desplegado.
     * @param _treasury Dirección del contrato WintonTreasury desplegado.
     */
    function setContracts(address _blue, address _red, address _treasury) external onlyOwner {
        // SEGURIDAD: Ninguna dirección puede ser cero (fondos irrecuperables).
        require(_blue != address(0) && _red != address(0) && _treasury != address(0), 
            "WintonProtocol: Invalid zero address");

        blueToken = IBlueToken(_blue);
        redToken = IRedToken(_red);
        treasury = _treasury;

        // Registro auditable de la configuración.
        emit ContractsUpdated(_blue, _red, _treasury);
    }

    /**
     * @notice Cambia la dirección del Relayer (backend que paga gas).
     * @dev Solo el Owner puede ejecutar. Útil si se rota la billetera del backend.
     * @param _newRelayer Nueva dirección del Relayer.
     */
    function setRelayer(address _newRelayer) external onlyOwner {
        require(_newRelayer != address(0), "WintonProtocol: Invalid zero address");
        emit RelayerUpdated(relayer, _newRelayer);
        relayer = _newRelayer;
    }

    /**
     * @notice Actualiza el estado KYC de una billetera en el Muro On-Chain.
     * @dev Solo el Owner puede ejecutar. Activa o desactiva la capacidad de
     * una billetera para participar en transacciones financieras.
     * @param _wallet Dirección de la billetera del usuario.
     * @param _status true = verificado (puede operar), false = bloqueado.
     */
    function setKYCStatus(address _wallet, bool _status) external onlyOwner {
        // SEGURIDAD: No permitir verificar la dirección cero.
        require(_wallet != address(0), "WintonProtocol: Invalid zero address");

        isKYCVerified[_wallet] = _status;

        // Registro auditable del cambio de estado KYC.
        emit KYCStatusUpdated(_wallet, _status);
    }

    /**
     * @notice Modifica la tasa de comisión porcentual de la plataforma.
     * @dev Solo el Owner puede ejecutar. Tiene un tope de seguridad del 50%.
     * Emite el evento ANTES de cambiar el valor para registrar el estado anterior.
     * @param _newRate Nueva tasa de comisión (ej: 5 = 5%, 10 = 10%).
     */
    function setCommissionRate(uint256 _newRate) external onlyOwner {
        // SEGURIDAD: Tope máximo para prevenir errores de configuración destructivos.
        require(_newRate <= 50, "WintonProtocol: Commission rate exceeds 50% safety cap");

        // Emitir evento con valor anterior y nuevo para auditoría comparativa.
        emit CommissionRateUpdated(commissionRate, _newRate);
        commissionRate = _newRate;
    }

    /**
     * @notice Modifica el límite máximo de tokens por transacción individual.
     * @dev Solo el Owner puede ejecutar. Actúa como un disyuntor (circuit breaker)
     * que previene que un error o un ataque pueda drenar cantidades catastróficas.
     * @param _newAmount Nuevo límite máximo (en wei, 18 decimales).
     */
    function setMaxTransactionAmount(uint256 _newAmount) external onlyOwner {
        require(_newAmount > 0, "WintonProtocol: Max amount must be greater than 0");
        emit MaxTransactionAmountUpdated(maxTransactionAmount, _newAmount);
        maxTransactionAmount = _newAmount;
    }

    /**
     * @notice Pausa todas las operaciones financieras del protocolo.
     * @dev Solo el Owner puede ejecutar. Usar en caso de emergencia de seguridad.
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Reanuda las operaciones financieras del protocolo.
     * @dev Solo el Owner puede ejecutar después de resolver la emergencia.
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // ========================================================================
    // FUNCIÓN PRINCIPAL: PROCESAMIENTO DE PAGOS
    // ========================================================================

    /**
     * @notice Procesa un pago entre dos usuarios verificados (KYC).
     * @dev Esta es la función más crítica del ecosistema. Ejecuta atómicamente:
     * 1. Validaciones de seguridad (KYC, dirección, monto).
     * 2. Minteo simultáneo de BLUE (activo) y RED (deuda) - Regla Balance Cero.
     * 3. Envío de comisión a la Tesorería.
     * 4. Auto-Amortización automática vía el Vigilante de BlueToken._update().
     *
     * FLUJO EIP-7702:
     * El backend verifica la firma del usuario, valida sus límites de crédito,
     * y luego llama a esta función como Relayer. El payer se pasa como parámetro
     * porque con EIP-7702 el backend patrocina la transacción.
     *
     * PROTECCIONES ACTIVAS:
     * - onlyRelayerOrOwner: Solo el backend o el Owner pueden llamar.
     * - nonReentrant: Bloquea ataques de reentrada.
     * - whenNotPaused: Respeta el estado de pausa de emergencia.
     * - KYC verificado para ambas partes.
     * - payer != payee (previene auto-pagos inflacionarios).
     * - treasury debe estar configurado.
     * - Circuit Breaker: límite máximo por transacción.
     *
     * @param payer Dirección de la billetera del pagador (verificada por el backend).
     * @param payee Dirección de la billetera que recibirá el pago en BLUE.
     * @param amountBlue Monto neto a pagar (en wei, 18 decimales).
     */
    function processPayment(
        address payer, 
        address payee, 
        uint256 amountBlue
    ) external onlyRelayerOrOwner nonReentrant whenNotPaused {

        // --- BLOQUE DE VALIDACIONES DE SEGURIDAD ---

        // SEGURIDAD: Ambos participantes deben estar verificados en el Muro KYC.
        require(isKYCVerified[payer], "WintonProtocol: Payer KYC not verified");
        require(isKYCVerified[payee], "WintonProtocol: Payee KYC not verified");

        // SEGURIDAD: El monto debe ser mayor a cero (previene transacciones vacías).
        require(amountBlue > 0, "WintonProtocol: Amount must be greater than 0");

        // SEGURIDAD: No se permite pagarse a sí mismo (previene inflación artificial).
        require(payer != payee, "WintonProtocol: Cannot pay yourself");

        // SEGURIDAD: La Tesorería debe estar configurada antes de procesar pagos.
        require(treasury != address(0), "WintonProtocol: Treasury not configured");

        // SEGURIDAD: Circuit Breaker - limitar monto máximo por transacción.
        require(amountBlue <= maxTransactionAmount, "WintonProtocol: Amount exceeds max per transaction");

        // --- BLOQUE DE CÁLCULO ECONÓMICO ---

        // Calcular la comisión de la plataforma sobre el monto del pago.
        uint256 fee = (amountBlue * commissionRate) / 100;
        // La deuda total del pagador incluye el pago neto + la comisión.
        uint256 totalDebt = amountBlue + fee;

        // --- BLOQUE DE MINTEO SIMULTÁNEO (REGLA DE BALANCE CERO) ---

        // PASO 1: Se crea la deuda RED para el pagador (totalDebt = pago + comisión).
        redToken.mintDebt(payer, totalDebt);
        // PASO 2: Se crea BLUE líquido para el beneficiario (solo el monto neto).
        // NOTA: El Vigilante de BlueToken._update() ejecuta la auto-amortización
        // automáticamente si el beneficiario tiene deuda RED previa.
        blueToken.mint(payee, amountBlue);
        // PASO 3: Se crea BLUE líquido para la Tesorería (solo la comisión).
        blueToken.mint(treasury, fee);

        // Registro auditable del pago procesado.
        emit PaymentProcessed(payer, payee, amountBlue, fee);
    }

    // ========================================================================
    // FUNCIÓN PÚBLICA: PUERTA DE SERVICIO PARA EL VIGILANTE
    // ========================================================================

    /**
     * @notice Punto de entrada público para activar la auto-amortización.
     * @dev Esta función es llamada automáticamente por el Vigilante de BlueToken
     * cada vez que alguien recibe BLUE. También puede ser llamada manualmente
     * por cualquier persona (es inofensiva: solo destruye, nunca crea).
     *
     * NO tiene nonReentrant porque debe poder ejecutarse dentro de processPayment
     * (que ya tiene nonReentrant). Es segura porque _autoAmortize solo llama
     * a burn/burnDebt, que son funciones controladas sin callbacks peligrosos.
     *
     * @param user Dirección del usuario cuyo balance será verificado.
     */
    function triggerAutoAmortize(address user) external {
        _autoAmortize(user);
    }

    // ========================================================================
    // FUNCIÓN INTERNA: AUTO-AMORTIZACIÓN (Materia-Antimateria)
    // ========================================================================

    /**
     * @notice Destruye simultáneamente saldo BLUE y deuda RED si coexisten.
     * @dev Implementa la Regla 2 de las Leyes Económicas:
     * "Es algorítmicamente imposible que un usuario posea BLUE líquido y
     * deuda RED al mismo tiempo". Si ambos existen, se aniquilan mutuamente
     * en la cantidad del menor de los dos (min(BLUE, RED)).
     * @param user Dirección del usuario cuyo balance será verificado.
     */
    function _autoAmortize(address user) internal {
        // Consultar los saldos actuales del usuario en ambos tokens.
        uint256 blueBalance = blueToken.balanceOf(user);
        uint256 redBalance = redToken.balanceOf(user);

        // Solo ejecutar si ambos saldos son positivos (la materia toca la antimateria).
        if (blueBalance > 0 && redBalance > 0) {
            // Calcular el menor de los dos para la aniquilación proporcional.
            uint256 amountToBurn = blueBalance < redBalance ? blueBalance : redBalance;

            // Destruir simultáneamente el BLUE y el RED del usuario.
            blueToken.burn(user, amountToBurn);
            redToken.burnDebt(user, amountToBurn);

            // Registro auditable de la auto-amortización ejecutada.
            emit AutoAmortization(user, amountToBurn);
        }
    }
}

contracts/WintonTreasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/// @dev Interfaz mínima del token BLUE para transferencias y consulta de saldo.
interface IBlueToken {
    function transfer(address to, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/**
 * @title WintonTreasury (La Bóveda del Ecosistema)
 * @author WintonCoin Protocol Team
 * @notice Bóveda programable que custodia las comisiones en BLUE real.
 * Permite a los Impulsores (Boosters) reclamar sus pagos (IOU -> BLUE)
 * mediante Árboles de Merkle.
 *
 * @dev ARQUITECTURA EIP-7702 (Pectra / Isthmus):
 * A diferencia de la versión ERC-2771, este contrato NO necesita un Trusted Forwarder.
 * Con EIP-7702, el Relayer patrocina la transacción y msg.sender es la
 * dirección real del usuario que reclama sus tokens.
 *
 * SEGURIDAD IMPLEMENTADA:
 * - Doble hashing en Merkle Leaf (previene colisiones con abi.encodePacked).
 * - Límite de 200 direcciones por resetClaims (previene DoS por exceso de gas).
 * - ReentrancyGuard en claim() y withdrawSurplus().
 * - Pausable en claim() para emergencias.
 * - Validación de saldo suficiente antes de cada transferencia.
 * - Patrón Check-Effects-Interactions (estado se actualiza ANTES de transferir).
 */
contract WintonTreasury is Ownable, ReentrancyGuard, Pausable {

    // ========================================================================
    // ESTADO
    // ========================================================================

    /// @notice Referencia al contrato del token BLUE para transferencias.
    IBlueToken public blueToken;

    /// @notice Billetera de los fundadores/empresa para recibir excedentes.
    address public foundersWallet;

    /// @notice Raíz de Merkle del ciclo actual (define quién puede cobrar y cuánto).
    bytes32 public currentMerkleRoot;

    /// @notice Límite máximo de direcciones por llamada a resetClaims.
    uint256 public constant MAX_RESET_BATCH = 200;

    /// @notice Registro de quién ya cobró en este ciclo (previene doble cobro).
    mapping(address => bool) public hasClaimed;

    // ========================================================================
    // EVENTOS
    // ========================================================================

    /// @notice Emitido cuando un Impulsor reclama exitosamente sus BLUE.
    event ClaimSuccessful(address indexed user, uint256 amount);

    /// @notice Emitido cuando el Owner actualiza la raíz de Merkle mensual.
    event MerkleRootUpdated(bytes32 newRoot);

    /// @notice Emitido cuando se configura o cambia la billetera fundadora.
    event FoundersWalletUpdated(address indexed newWallet);

    /// @notice Emitido cuando el Owner retira excedentes a la billetera fundadora.
    event SurplusWithdrawn(address indexed to, uint256 amount);

    /// @notice Emitido cuando el Owner resetea los estados de cobro.
    event ClaimsReset(uint256 count);

    // ========================================================================
    // CONSTRUCTOR
    // ========================================================================

    /**
     * @notice Inicializa la Tesorería con el token BLUE.
     * @dev Con EIP-7702, no se necesita Trusted Forwarder.
     * @param _blueToken Dirección del contrato BlueToken desplegado.
     */
    constructor(address _blueToken) Ownable(msg.sender) {
        // SEGURIDAD: El token BLUE debe ser una dirección válida.
        require(_blueToken != address(0), "Treasury: Invalid BlueToken address");
        blueToken = IBlueToken(_blueToken);
    }

    /**
     * @notice BLOQUEADO. No se permite renunciar a la propiedad del contrato.
     * @dev Sobreescribe Ownable.renounceOwnership() para prevenir que el protocolo
     * quede permanentemente sin administrador. En su lugar, usar transferOwnership()
     * para migrar el control a un Gnosis Safe (multisig) en producción.
     */
    function renounceOwnership() public pure override {
        revert("Treasury: Ownership renunciation is disabled");
    }

    // ========================================================================
    // FUNCIONES DE CONFIGURACIÓN (Solo Owner)
    // ========================================================================

    /**
     * @notice Configura o actualiza la billetera de los fundadores.
     * @dev Solo el Owner puede ejecutar. Flexible para cambios futuros
     * (ej: migrar de hot wallet a cold wallet o multisig).
     * @param _newWallet Dirección de la nueva billetera fundadora.
     */
    function setFoundersWallet(address _newWallet) external onlyOwner {
        // SEGURIDAD: Prevenir configuración a dirección vacía.
        require(_newWallet != address(0), "Treasury: Invalid zero address");
        foundersWallet = _newWallet;
        emit FoundersWalletUpdated(_newWallet);
    }

    /**
     * @notice Actualiza la raíz de Merkle para el ciclo de pagos actual.
     * @dev Solo el Owner puede ejecutar. El backend calcula la Cascada de Pagos
     * (Prioridad Humanitaria -> Visionarios -> Pioneros -> Guardianes),
     * genera el árbol de Merkle y sube la raíz aquí.
     * @param _merkleRoot Nueva raíz criptográfica del árbol de derechos de cobro.
     */
    function setMerkleRoot(bytes32 _merkleRoot) external onlyOwner {
        currentMerkleRoot = _merkleRoot;
        emit MerkleRootUpdated(_merkleRoot);
    }

    /**
     * @notice Reinicia el estado de cobro para un lote de usuarios (nuevo ciclo mensual).
     * @dev Solo el Owner puede ejecutar. Limitado a MAX_RESET_BATCH (200) por llamada
     * para prevenir ataques de DoS por exceso de gas en el bloque.
     * @param users Array de direcciones cuyos estados de cobro serán reiniciados.
     */
    function resetClaims(address[] calldata users) external onlyOwner {
        // SEGURIDAD: Limitar tamaño del array para prevenir DoS por gas.
        require(users.length <= MAX_RESET_BATCH, "Treasury: Batch too large (max 200)");

        // Reiniciar el estado de cobro de cada dirección.
        for (uint256 i = 0; i < users.length; i++) {
            hasClaimed[users[i]] = false;
        }

        // Registro auditable de la cantidad de resets ejecutados.
        emit ClaimsReset(users.length);
    }

    /**
     * @notice Pausa los reclamos de la Tesorería en caso de emergencia.
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Reanuda los reclamos de la Tesorería tras resolver la emergencia.
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // ========================================================================
    // FUNCIÓN PRINCIPAL: RECLAMO DE IOU -> BLUE (Merkle Claim)
    // ========================================================================

    /**
     * @notice Permite a un Impulsor reclamar sus BLUE.
     * @dev Con EIP-7702, msg.sender ES el usuario real (la transacción
     * es patrocinada por el Relayer, pero msg.sender apunta al EOA del usuario).
     *
     * Ejecuta el patrón Check-Effects-Interactions:
     * 1. CHECK: Verifica que no haya cobrado, que la raíz exista y la prueba sea válida.
     * 2. EFFECTS: Marca al usuario como "ya cobró" ANTES de transferir.
     * 3. INTERACTIONS: Transfiere los tokens BLUE al usuario.
     *
     * SEGURIDAD: Usa doble hashing (keccak256(bytes.concat(keccak256(abi.encode(...)))))
     * para prevenir colisiones de segundo preimagen en el árbol de Merkle.
     *
     * @param amount Cantidad de BLUE que el usuario tiene derecho a reclamar.
     * @param merkleProof Prueba criptográfica de inclusión en el árbol de Merkle.
     */
    function claim(uint256 amount, bytes32[] calldata merkleProof) external nonReentrant whenNotPaused {
        // Con EIP-7702, msg.sender ES la dirección real del usuario.
        address user = msg.sender;

        // --- BLOQUE CHECK ---

        // SEGURIDAD: No permitir doble cobro en el mismo ciclo.
        require(!hasClaimed[user], "Treasury: Already claimed this month");

        // SEGURIDAD: La raíz de Merkle debe estar activa.
        require(currentMerkleRoot != bytes32(0), "Treasury: Merkle root not set");

        // SEGURIDAD: El monto debe ser positivo.
        require(amount > 0, "Treasury: Amount must be greater than 0");

        // Construir la "hoja" del árbol de Merkle con doble hashing (estándar OpenZeppelin).
        bytes32 leaf = keccak256(bytes.concat(keccak256(abi.encode(user, amount))));

        // Verificar criptográficamente que esta hoja pertenece al árbol autorizado.
        require(MerkleProof.verify(merkleProof, currentMerkleRoot, leaf), 
            "Treasury: Invalid Merkle Proof");

        // SEGURIDAD: Verificar que la bóveda tiene suficiente liquidez.
        require(blueToken.balanceOf(address(this)) >= amount, 
            "Treasury: Insufficient liquidity");

        // --- BLOQUE EFFECTS (Estado se actualiza ANTES de la transferencia) ---

        // Marcar como cobrado ANTES de transferir (Patrón CEI: previene reentrada).
        hasClaimed[user] = true;

        // --- BLOQUE INTERACTIONS (Interacción externa DESPUÉS de actualizar estado) ---

        // Transferir los tokens BLUE reales a la billetera del Impulsor.
        require(blueToken.transfer(user, amount), "Treasury: Transfer failed");

        // Registro auditable del reclamo exitoso.
        emit ClaimSuccessful(user, amount);
    }

    // ========================================================================
    // FUNCIÓN DE RETIRO DE EXCEDENTES (Solo Owner)
    // ========================================================================

    /**
     * @notice Retira excedentes de ganancias a la billetera de los fundadores.
     * @dev Solo el Owner puede ejecutar. Solo debe usarse DESPUÉS de que todos
     * los Impulsores del ciclo hayan tenido oportunidad de reclamar.
     * @param amount Cantidad de BLUE a retirar como ganancia neta.
     */
    function withdrawSurplus(uint256 amount) external onlyOwner nonReentrant {
        // SEGURIDAD: La billetera fundadora debe estar configurada.
        require(foundersWallet != address(0), "Treasury: Founders wallet not set");

        // SEGURIDAD: Debe haber fondos suficientes para el retiro.
        require(blueToken.balanceOf(address(this)) >= amount, "Treasury: Insufficient funds");

        // Transferir los excedentes a la billetera fundadora.
        require(blueToken.transfer(foundersWallet, amount), "Treasury: Transfer failed");

        // Registro auditable del retiro ejecutado.
        emit SurplusWithdrawn(foundersWallet, amount);
    }
}

